
import os, re, sqlite3, hashlib
from datetime import datetime
import streamlit as st

st.set_page_config(page_title="ARISE", page_icon="âš”ï¸", layout="centered", initial_sidebar_state="collapsed")

DB_PATH = "arise.db"
DEFAULT_QUESTS = ["100 Push-ups","100 Sit-ups","100 Squats","Plan tomorrow","No sugar today"]

def get_conn():
    conn = sqlite3.connect(DB_PATH); conn.execute("PRAGMA foreign_keys = ON"); return conn

def init_db():
    with get_conn() as c:
        c.execute("CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, email TEXT UNIQUE, salt TEXT, password_hash TEXT, created_at TEXT)")
        c.execute("CREATE TABLE IF NOT EXISTS quests (id INTEGER PRIMARY KEY, user_id INTEGER, quest_name TEXT, completed INTEGER DEFAULT 0, updated_at TEXT, UNIQUE(user_id, quest_name), FOREIGN KEY(user_id) REFERENCES users(id))")
init_db()

def hash_pwd(p,s=None):
    if s is None: s=os.urandom(16).hex()
    h=hashlib.pbkdf2_hmac("sha256",p.encode(),bytes.fromhex(s),120000).hex()
    return s,h

def create_user(e,p):
    e=e.strip().lower(); s,h=hash_pwd(p)
    try:
        with get_conn() as c:
            cur=c.cursor()
            cur.execute("INSERT INTO users(email,salt,password_hash,created_at) VALUES(?,?,?,?)",(e,s,h,datetime.utcnow().isoformat()))
            uid=cur.lastrowid
            for q in DEFAULT_QUESTS: cur.execute("INSERT OR IGNORE INTO quests(user_id,quest_name,completed,updated_at) VALUES(?,?,0,?)",(uid,q,datetime.utcnow().isoformat()))
        return True,uid
    except: return False,None

def auth(e,p):
    e=e.strip().lower()
    with get_conn() as c:
        r=c.execute("SELECT id,salt,password_hash FROM users WHERE email=?",(e,)).fetchone()
    if not r: return None
    uid,s,sh=r; _,h=hash_pwd(p,s)
    return uid if h==sh else None

def get_q(uid):
    with get_conn() as c: return c.execute("SELECT quest_name,completed FROM quests WHERE user_id=? ORDER BY id",(uid,)).fetchall()

def save_q(uid,state):
    now=datetime.utcnow().isoformat()
    with get_conn() as c:
        for n,d in state.items(): c.execute("UPDATE quests SET completed=?,updated_at=? WHERE user_id=? AND quest_name=?",(1 if d else 0,now,uid,n))

