if 'uid' not in st.session_state: st.session_state.uid=None

if not st.session_state.uid:
    st.markdown('<div class="login-wrap"><div class="spacer"></div>', unsafe_allow_html=True)
    email = st.text_input("", placeholder="Email or Username", label_visibility="collapsed")
    pwd = st.text_input("", type="password", placeholder="Password", label_visibility="collapsed")
    st.markdown('<div class="forgot"><a>Forgot Password?</a></div>', unsafe_allow_html=True)
    c1,c2 = st.columns(2)
    with c1: login = st.button("LOGIN")
    with c2: signup = st.button("CREATE")
    st.markdown('<div class="divider"><span>OR</span></div>', unsafe_allow_html=True)
    st.markdown('<div class="google-btn">', unsafe_allow_html=True); st.button("Continue with Google", disabled=True, use_container_width=True); st.markdown('</div>', unsafe_allow_html=True)
    st.markdown('<div class="signup">New here? <span>Create Account</span></div>', unsafe_allow_html=True)
    st.markdown('</div>', unsafe_allow_html=True)
    if login:
        uid = auth(email,pwd) if email and pwd else None
        if uid: st.session_state.uid=uid; st.rerun()
        else: st.error("Wrong email or password")
    if signup:
        if email and pwd and len(pwd)>=6:
            ok,uid = create_user(email,pwd)
            if ok: st.session_state.uid=uid; st.rerun()
            else: st.error("Account exists")
        else: st.error("Use 6+ character password")
else:
    qs = get_q(st.session_state.uid); done = sum(d for _,d in qs)
    st.markdown('<div class="dash">', unsafe_allow_html=True)
    st.markdown('<div class="glass-card">', unsafe_allow_html=True)
    st.markdown('<div class="player">PLAYER</div>', unsafe_allow_html=True)
    st.markdown(f"<div style='color:rgba(255,255,255,0.7);margin-top:4px'>LV.1 â€¢ {done*20} XP â€¢ {done}/{len(qs)} Complete</div>", unsafe_allow_html=True)
    st.markdown('<div class="stat-grid">', unsafe_allow_html=True)
    for lab in ["STR","AGI","INT","VIT","PER"]:
        st.markdown(f"<div class='stat'><div class='stat-val'>10</div><div class='stat-lab'>{lab}</div></div>", unsafe_allow_html=True)
    st.markdown('</div></div>', unsafe_allow_html=True)
    st.markdown('<div class="glass-card">', unsafe_allow_html=True)
    st.markdown("<div style='color:white;font-weight:600;margin-bottom:12px'>Daily Quests</div>", unsafe_allow_html=True)
    state = {}
    for n,d in qs:
        k = re.sub(r'[^a-z0-9]','_',n.lower())
        state[n] = st.checkbox(n, value=bool(d), key=k)
    st.markdown('</div>', unsafe_allow_html=True)
    if st.button("SAVE PROGRESS", use_container_width=True): save_q(st.session_state.uid, state); st.success("Synced!"); st.rerun()
    if st.button("LOGOUT", use_container_width=True): st.session_state.uid=None; st.rerun()
    st.markdown('</div>', unsafe_allow_html=True)
